        path.addQuadCurve(to: CGPoint(x: 269.18, y: 28.03), control: CGPoint(x: 267.1, y: 26.22))
        path.addQuadCurve(to: CGPoint(x: 276.51, y: 30.91), control: CGPoint(x: 271.27, y: 29.83))
        path.addLine(to: CGPoint(x: 287.75, y: 33.3))
        path.addQuadCurve(to: CGPoint(x: 302.37, y: 40.06), control: CGPoint(x: 297.56, y: 35.4))
        path.addQuadCurve(to: CGPoint(x: 307.19, y: 52.31), control: CGPoint(x: 307.19, y: 44.71))
        path.addQuadCurve(to: CGPoint(x: 305.16, y: 61.34), control: CGPoint(x: 307.19, y: 57.3))
        path.addQuadCurve(to: CGPoint(x: 299.36, y: 68.27), control: CGPoint(x: 303.14, y: 65.38))
        path.addQuadCurve(to: CGPoint(x: 290.3, y: 72.71), control: CGPoint(x: 295.59, y: 71.16))
        path.addQuadCurve(to: CGPoint(x: 278.39, y: 74.26), control: CGPoint(x: 285.01, y: 74.26))
        path.closeSubpath()
        return path
    }()

    /// A four-point glint with equal arms and concave sides, the logo's shape.
    private static func glint(center c: CGPoint, arm: CGFloat) -> Path {
        let p = arm * 0.18
        var path = Path()
        path.move(to: CGPoint(x: c.x, y: c.y - arm))
        path.addQuadCurve(to: CGPoint(x: c.x + arm, y: c.y), control: CGPoint(x: c.x + p, y: c.y - p))
        path.addQuadCurve(to: CGPoint(x: c.x, y: c.y + arm), control: CGPoint(x: c.x + p, y: c.y + p))
        path.addQuadCurve(to: CGPoint(x: c.x - arm, y: c.y), control: CGPoint(x: c.x - p, y: c.y + p))
        path.addQuadCurve(to: CGPoint(x: c.x, y: c.y - arm), control: CGPoint(x: c.x - p, y: c.y - p))
        path.closeSubpath()
        return path
    }

    private static func adaptive(dark: NSColor, light: NSColor) -> Color {
        Color(nsColor: NSColor(name: nil) { appearance in
            appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua ? dark : light
        })
    }
}
